SELECT jsonb_build_object(
'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',CASE WHEN tn.nspname='public' THEN 'public.'||quote_ident(t.typname) ELSE format_type(a.atttypid,a.atttypmod) END,'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity) ORDER BY a.attnum) FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid JOIN pg_namespace tn ON tn.oid=t.typnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',con.conname,'type',con.contype,'definition',pg_get_constraintdef(con.oid))),'[]'::jsonb) FROM pg_constraint con WHERE con.conrelid=c.oid),
'primary_key',(SELECT jsonb_agg(a.attname ORDER BY k.ord) FROM pg_constraint con JOIN LATERAL unnest(con.conkey) WITH ORDINALITY k(num,ord) ON true JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum=k.num WHERE con.conrelid=c.oid AND con.contype='p'),
'indexes',(SELECT coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid)),'[]'::jsonb) FROM pg_index i WHERE i.indrelid=c.oid AND NOT EXISTS(SELECT 1 FROM pg_constraint x WHERE x.conindid=i.indexrelid))) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' AND c.relname IN ('customers','conversation_states','message_logs','processed_webhook_events','dashboard_admins','catalog_assets','handoff_deliveries','crm_control_commands','crm_send_attempts','crm_media_assets')),
'enums',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.typname,'values',(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid))),'[]'::jsonb) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typtype='e'),
'sequences',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',sequencename,'type',data_type,'start',start_value::text,'min',min_value::text,'max',max_value::text,'increment',increment_by::text,'cycle',cycle,'cache',cache_size::text)),'[]'::jsonb) FROM pg_sequences WHERE schemaname='public'),
'functions',(SELECT coalesce(jsonb_agg(pg_get_functiondef(p.oid)),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'crm_%' AND p.prokind='f')) AS manifest;
